def test_orders_negative_paths():
    username = f"user_{uuid.uuid4().hex[:8]}"

    # Register
    requests.post(get_url("user", "/register"), json={
        "username": username, "password": "pw", "email": f"{username}@test.com",
        "firstName": "F", "lastName": "L"
    }, timeout=10)

    # Add Item to Cart
    requests.post(get_url("carts", f"/carts/{username}/items"), json={
        "itemId": "item1", "quantity": 1, "unitPrice": 10.0
    }, timeout=10)

    # 1. Missing required field (address) -> 406
    order_payload_missing = {
        "customer": f"/customers/{username}",
        "card": f"/cards/{username}:1234",
        "items": f"/carts/{username}/items"
    }
    resp = requests.post(get_url("orders", "/orders"), json=order_payload_missing, timeout=10)
    assert resp.status_code == 406, f"Expected 406, got {resp.status_code}: {resp.text}"

    # 2. Syntactically invalid composite ID for address -> 404
    order_payload_invalid_id = {
        "customer": f"/customers/{username}",
        "address": "/addresses/invalid_id_format",
        "card": f"/cards/{username}:1234",
        "items": f"/carts/{username}/items"
    }
    resp = requests.post(get_url("orders", "/orders"), json=order_payload_invalid_id, timeout=10)
    assert resp.status_code == 404, f"Expected 404, got {resp.status_code}: {resp.text}"
